// OBX - Observation/Result
// The OBX segment is used to transmit a single observation or observation fragment. It represents the smallest indivisible unit of a report. The OBX segment can also contain encapsulated data, e.g., a CDA document or a DICOM image.
type OBX struct {
	SetIDOBX                              *SI      `hl7:"1"`
	ValueType                             *ID      `hl7:"2"`
	ObservationIdentifier                 *CWE     `hl7:"3,required"`
	ObservationSubID                      *ST      `hl7:"4"`
	ObservationValue                      []VARIES `hl7:"5"`
	Units                                 *CWE     `hl7:"6"`
	ReferencesRange                       *ST      `hl7:"7"`
	AbnormalFlags                         []IS     `hl7:"8"`
	Probability                           *NM      `hl7:"9"`
	NatureOfAbnormalTest                  []ID     `hl7:"10"`
	ObservationResultStatus               *ID      `hl7:"11,required"`
	EffectiveDateOfReferenceRange         *DTM     `hl7:"12"`
	UserDefinedAccessChecks               *ST      `hl7:"13"`
	DateTimeOfTheObservation              *DTM     `hl7:"14"`
	ProducerSID                           *CWE     `hl7:"15"`
	ResponsibleObserver                   []XCN    `hl7:"16"`
	ObservationMethod                     []CWE    `hl7:"17"`
	EquipmentInstanceIdentifier           []EI     `hl7:"18"`
	DateTimeOfTheAnalysis                 *DTM     `hl7:"19"`
	ObservationSite                       []CWE    `hl7:"20"`
	ObservationInstanceIdentifier         *EI      `hl7:"21"`
	MoodCode                              *CNE     `hl7:"22"`
	PerformingOrganizationName            *XON     `hl7:"23"`
	PerformingOrganizationAddress         *XAD     `hl7:"24"`
	PerformingOrganizationMedicalDirector *XCN     `hl7:"25"`
}

func NewOBX() *OBX {
	return &OBX{}
}

func (s *OBX) Validate() error {

	if s.ObservationIdentifier == nil {
		return fmt.Errorf("OBX.ObservationIdentifier is required")
	}
	if s.ObservationIdentifier != nil {
		if err := s.ObservationIdentifier.Validate(); err != nil {
			return fmt.Errorf("OBX.ObservationIdentifier: %w", err)
		}
	}

	for _, item := range s.ObservationValue {
		if string(item) == "" {
			return fmt.Errorf("OBX.ObservationValue item is empty")
		}
	}

	if s.Units != nil {
		if err := s.Units.Validate(); err != nil {
			return fmt.Errorf("OBX.Units: %w", err)
		}
	}

	for _, item := range s.AbnormalFlags {
		if string(item) == "" {
			return fmt.Errorf("OBX.AbnormalFlags item is empty")
		}
	}

	for _, item := range s.NatureOfAbnormalTest {
		if string(item) == "" {
			return fmt.Errorf("OBX.NatureOfAbnormalTest item is empty")
		}
	}

	if s.ObservationResultStatus == nil {
		return fmt.Errorf("OBX.ObservationResultStatus is required")
	}
	if string(*s.ObservationResultStatus) == "" {
		return fmt.Errorf("OBX.ObservationResultStatus is empty")
	}

	if s.ProducerSID != nil {
		if err := s.ProducerSID.Validate(); err != nil {
			return fmt.Errorf("OBX.ProducerSID: %w", err)
		}
	}

	for _, item := range s.ResponsibleObserver {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OBX.ResponsibleObserver: %w", err)
		}
	}

	for _, item := range s.ObservationMethod {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OBX.ObservationMethod: %w", err)
		}
	}

	for _, item := range s.EquipmentInstanceIdentifier {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OBX.EquipmentInstanceIdentifier: %w", err)
		}
	}

	for _, item := range s.ObservationSite {
		if err := item.Validate(); err != nil {
			return fmt.Errorf("OBX.ObservationSite: %w", err)
		}
	}

	if s.ObservationInstanceIdentifier != nil {
		if err := s.ObservationInstanceIdentifier.Validate(); err != nil {
			return fmt.Errorf("OBX.ObservationInstanceIdentifier: %w", err)
		}
	}

	if s.MoodCode != nil {
		if err := s.MoodCode.Validate(); err != nil {
			return fmt.Errorf("OBX.MoodCode: %w", err)
		}
	}

	if s.PerformingOrganizationName != nil {
		if err := s.PerformingOrganizationName.Validate(); err != nil {
			return fmt.Errorf("OBX.PerformingOrganizationName: %w", err)
		}
	}

	if s.PerformingOrganizationAddress != nil {
		if err := s.PerformingOrganizationAddress.Validate(); err != nil {
			return fmt.Errorf("OBX.PerformingOrganizationAddress: %w", err)
		}
	}

	if s.PerformingOrganizationMedicalDirector != nil {
		if err := s.PerformingOrganizationMedicalDirector.Validate(); err != nil {
			return fmt.Errorf("OBX.PerformingOrganizationMedicalDirector: %w", err)
		}
	}
	return nil
}

